window.PhoneExperience={create(ctx){
 'use strict';
 const {data:D,gallery:G,esc,icon,btn,shell,go,save,toast,modal,appIcon}=ctx;
 const S=()=>ctx.getState(),people=D.people,wang=people[0].id;
 let tab='chats',playing=null,audio=null,activeUrl=null,mediaMenu=false,emojiMenu=false,voiceMode=false,calcValue='0',calcStored=null,calcOp=null,calcFresh=false;
 const chatViews=new Map();let nextCaret=null,forceChatEnd=null;
 const wangPortrait='assets/photos/xiaowang/xiaowang_06_windy_selfie.jpg';
 const selfPortrait='assets/photos/fitness/fitness_01_black_vest.jpg';
 const upload=document.createElement('input');upload.type='file';upload.accept='audio/*,.mp3,.m4a,.wav,.ogg';upload.id='chat-audio-file';upload.hidden=true;document.body.appendChild(upload);
 const person=id=>people.find(p=>p.id===id)||people[0];
 const photoList=albumId=>{const a=G.albums.find(x=>x.id===albumId);return (a?.items||[]).map(id=>G.assets.find(x=>x.id===id)).filter(Boolean);};
 const avatar=(p,self=false)=>`<span class="wx-avatar" style="--accent:${esc(p.color||'#79958a')}">${p.id===wang||self?`<img src="${self?selfPortrait:wangPortrait}" alt="${self?'小圣':esc(p.name)}" class="${self?'self-avatar':'wang-avatar'}">`:esc(p.initial)}</span>`;
 // Authored game dialogue requested by the user; never treated as verified quotations.
 const wangStory=[
  {type:'photo',assetId:'xiaowang-07',from:'other'},
  ...[
   ['other','这张拍得怎么样？'],
   ['self','风景一般。'],
   ['other','？给你一次重新组织语言的机会'],
   ['self','光顾着看你，没看风景。'],
   ['other','行，今天嘴还挺甜😌'],
   ['self','那有奖励吗？'],
   ['other','奖励你下次继续给我拍照'],
   ['self','包拍，包拎包，还包陪你吃饭。'],
   ['other','那我要吃你那份的第一口'],
   ['self','第一口给你，最后一口也给你。'],
   ['other','中间的呢？'],
   ['self','中间的得留点体力，牵你回家。'],
   ['other','少贫，外面风大，你多穿一件'],
   ['self','知道啦。你帽子扶好，别跟风跑了。'],
   ['other','放心，跑也拉着你一起'],
   ['self','那我可不松手了。'],
   ['other','本来也没让你松呀🤍']
  ].map(([from,text])=>({type:'text',from,text}))
 ].map((m,i)=>({id:'wang-story-20261024-'+i,...m}));
 const messages=id=>[...(id===wang?wangStory:[]),...(window.CHAT_ORIGINALS?.[id]||[]),...(S().chatMessages[id]||[])];
 const messagePhoto=m=>{const id=m.assetId||['xiaowang-01','xiaowang-02','xiaowang-03','xiaowang-04','xiaowang-05','xiaowang-06'][m.index];return photoList('xiaowang').find(p=>p.id===id);};
 function messageBubble(m,p){if(m.type==='voice')return voiceBubble(m,p);const outgoing=m.from==='self';if(m.type==='photo'){const asset=messagePhoto(m),index=photoList('xiaowang').findIndex(p=>p.id===asset?.id);return asset?`<div class="wx-message ${outgoing?'outgoing':'incoming'}">${avatar(p,outgoing)}<button class="wx-photo-bubble" data-action="wx-photo" data-index="${index}"><img src="${esc(asset.path)}" alt="${esc(asset.description)}"></button></div>`:'';}return `<div class="wx-message ${outgoing?'outgoing':'incoming'}" ${m.autoReply?'data-auto-reply="true"':''}>${avatar(p,outgoing)}<div class="wx-text-bubble">${esc(m.text)}</div></div>`;}

 const R=window.WangChatRuntime.create({getState:S,getRoute:ctx.getRoute,wang,save,renderBubble:m=>messageBubble(m,person(wang)),refreshList(){const list=document.getElementById('wx-contact-list');if(list){const q=(document.getElementById('wx-contact-search')?.value||'').trim().toLowerCase();list.innerHTML=rows(people.filter(p=>(p.name+' '+(p.alias||'')).toLowerCase().includes(q)));}const tab=document.querySelector('.wx-tabs [data-tab="chats"] .wx-tab-symbol');if(tab){tab.querySelector('.wx-tab-badge')?.remove();if(unreadCount())tab.insertAdjacentHTML('beforeend','<b class="wx-tab-badge">'+unreadCount()+'</b>');}const button=document.querySelector('.app-grid [data-app="wechat"]');if(button){button.querySelector('.badge')?.remove();if(unreadCount())button.insertAdjacentHTML('beforeend','<span class="badge">'+unreadCount()+'</span>');}}});
 const unread=id=>id===wang&&!S().chatReadRooms.includes(id)?1:0;
 function unreadCount(){return people.reduce((n,p)=>n+unread(p.id),0);}
 function markRead(id){if(!S().chatReadRooms.includes(id)){S().chatReadRooms.push(id);save();}}
 function stopAudio(){if(audio){audio.pause();audio=null;}if(activeUrl){URL.revokeObjectURL(activeUrl);activeUrl=null;}playing=null;document.querySelectorAll('.wx-voice.playing').forEach(el=>el.classList.remove('playing'));}
 const dbPromise=new Promise(resolve=>{if(!window.indexedDB){resolve(null);return;}const r=indexedDB.open('xiaosheng-phone-media',1);r.onupgradeneeded=()=>r.result.createObjectStore('audio');r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null);});
 async function mediaStore(id,blob){const db=await dbPromise;if(!db)throw Error('storage');return new Promise((resolve,reject)=>{const tx=db.transaction('audio','readwrite');tx.objectStore('audio').put(blob,id);tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error);});}
 async function mediaLoad(id){const db=await dbPromise;if(!db)return null;return new Promise(resolve=>{const r=db.transaction('audio','readonly').objectStore('audio').get(id);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>resolve(null);});}
 function nav(title,body,{className='',right='',footer='',large=false}={}){return `<section class="app-shell wx-shell ${className}"><nav class="wx-nav"><div class="wx-left">${btn('back',icon('back'),'','aria-label="返回桌面"')}</div><h1>${esc(title)}</h1><div class="wx-right">${right}</div></nav><div class="app-scroll wx-scroll ${large?'wx-large':''}">${body}</div>${footer}</section>`;}
 function tabs(){return `<nav class="wx-tabs">${[['chats','bubble','微信'],['contacts','user','通讯录'],['discover','compass','发现'],['me','user','我']].map(([id,i,label])=>`<button data-action="wx-tab" data-tab="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}"><span class="wx-tab-symbol">${icon(i)}${id==='chats'&&unreadCount()?`<b class="wx-tab-badge">${unreadCount()}</b>`:''}</span><span>${label}</span></button>`).join('')}</nav>`;}
 function rows(list=people){if(!list.length)return '<p class="wx-search-empty" role="status">没有找到联系人，试试换个名字</p>';return list.map(p=>{const ms=messages(p.id),last=ms.at(-1);const preview=last?(last.type==='voice'?'[语音]':last.type==='photo'?'[图片]':last.text):p.id===wang?'[图片]':'暂无消息';return `<button class="wx-contact ${p.id===wang?'pinned':''}" data-action="room" data-id="${p.id}"><span class="wx-avatar-wrap">${avatar(p)}${unread(p.id)?'<b class="wx-unread">1</b>':''}</span><span class="wx-contact-copy"><strong>${esc(p.name)}</strong><small>${esc(preview)}</small></span><span class="wx-contact-end">${last?.time?esc(last.time):''}</span></button>`;}).join('');}
 function wechat(){
  let body='',right=btn('wx-options',icon('plus'),'','aria-label="微信菜单"');
  if(tab==='chats')body=`<label class="wx-search">${icon('search')}<input id="wx-contact-search" type="search" placeholder="搜索" aria-label="搜索微信联系人"></label><div id="wx-contact-list">${rows()}</div>`;
  if(tab==='contacts')body=`<div class="wx-contact-tools">${btn('wx-new',`<span class="wx-tool-icon">${icon('plus')}</span>新的朋友`,'wx-setting-row')}${btn('favorites',`<span class="wx-tool-icon gold">${icon('star')}</span>收藏`,'wx-setting-row')}</div><div class="wx-section-label">联系人</div>${people.map(p=>`<button class="wx-person-row" data-action="room" data-id="${p.id}">${avatar(p)}<span>${esc(p.name)}</span></button>`).join('')}`;
  if(tab==='discover')body=`<div class="wx-group">${btn('wx-moments',`<span class="wx-tool-icon blue">${icon('compass')}</span><span>朋友圈</span><span class="wx-row-end">${icon('chevron')}</span>`,'wx-setting-row')}${btn('app',`<span class="wx-tool-icon gold">${icon('grid')}</span><span>照片</span><span class="wx-row-end">${icon('chevron')}</span>`,'wx-setting-row','data-app="photos"')}</div><div class="wx-discover-photos">${photoList('xiaowang').slice(0,3).map((a,i)=>`<button data-action="wx-photo" data-index="${i}"><img src="${esc(a.path)}" alt="${esc(a.description)}"></button>`).join('')}</div>`;
  if(tab==='me')body=`<div class="wx-profile">${avatar({id:'self'},true)}<div><h2>小圣</h2><p>照片、收藏与生活</p></div>${btn('wx-self-album',icon('chevron'),'','aria-label="我的照片"')}</div><div class="wx-group">${btn('favorites',`<span class="wx-tool-icon gold">${icon('star')}</span><span>收藏</span><span class="wx-row-end">${icon('chevron')}</span>`,'wx-setting-row')}${btn('wx-moments',`<span class="wx-tool-icon blue">${icon('grid')}</span><span>朋友圈</span><span class="wx-row-end">${icon('chevron')}</span>`,'wx-setting-row')}${btn('app',`<span class="wx-tool-icon">${icon('folder')}</span><span>文件</span><span class="wx-row-end">${icon('chevron')}</span>`,'wx-setting-row','data-app="files"')}</div><div class="wx-group">${btn('app',`<span class="wx-tool-icon">${icon('sun')}</span><span>设置</span><span class="wx-row-end">${icon('chevron')}</span>`,'wx-setting-row','data-app="settings"')}</div><div class="wx-group"><button type="button" class="wx-setting-row" data-dev-support><span class="wx-tool-icon gold" aria-hidden="true">🌶️</span><span class="wx-support-copy">支持开发者<small>微信 ¥0.99 · 自愿支持</small></span><span class="wx-row-end">${icon('chevron')}</span></button></div>`;
  return nav(tab==='chats'?'微信':tab==='contacts'?'通讯录':tab==='discover'?'发现':'我',body,{right,footer:tabs(),className:tab==='me'||tab==='discover'?'wx-muted':''});
 }
 function voiceBubble(m,p){const listened=S().playedVoiceIds.includes(m.id);return `<div class="wx-message ${m.from==='self'?'outgoing':'incoming'}"><span>${avatar(p,m.from==='self')}</span><div class="wx-voice-wrap"><button class="wx-voice ${playing===m.id?'playing':''}" style="width:${Math.min(215,92+(m.duration||1)*4)}px" data-action="wx-voice" data-id="${esc(m.id)}" data-room="${p.id}" aria-label="播放语音 ${Math.ceil(m.duration||0)}秒"><span class="wx-voice-waves"><i></i><i></i><i></i></span><b>${Math.ceil(m.duration||0)}″</b></button>${!listened?'<i class="wx-voice-unheard" aria-label="未听语音"></i>':''}</div></div>`;}
 function room(){const p=person(ctx.getRoute().id);markRead(p.id);const ms=messages(p.id);const photos=p.id===wang?photoList('xiaowang'):[];
  return `<section class="app-shell wx-shell wx-room"><nav class="wx-nav"><div class="wx-left">${btn('back',icon('back'),'','aria-label="返回微信"')}</div><h1>${esc(p.name)}</h1><div class="wx-right">${btn('wx-room-info',icon('dots'),'','aria-label="聊天详情"')}</div></nav><div class="app-scroll wx-chat-scroll" data-room-id="${esc(p.id)}"><div class="wx-chat-start">${p.id===wang?'小王':esc(p.name)}</div>${photos.length?`<div class="wx-shared-album"><div class="wx-shared-top"><span>${icon('grid')} 和小王</span>${btn('wx-album','查看全部 '+icon('chevron'))}</div><div class="wx-shared-grid">${photos.map((a,i)=>`<button data-action="wx-photo" data-index="${i}" aria-label="查看照片 ${i+1}"><img src="${esc(a.path)}" alt="${esc(a.description)}" decoding="async"></button>`).join('')}</div></div>`:`<div class="wx-no-messages">${avatar(p)}<span>${esc(p.name)}</span></div>`}${ms.map(m=>messageBubble(m,p)).join('')}${p.id===wang?R.typingMarkup(avatar(p)):''}<div id="wx-chat-bottom"></div></div><form class="wx-composer" data-form="wx-message"><button type="button" data-action="wx-mic" aria-label="语音消息">${icon(voiceMode?'edit':'volume')}</button>${voiceMode?btn('wx-import','导入原声','wx-hold-voice','type="button"'):`<textarea id="wx-message-input" aria-label="消息" rows="1" maxlength="1000">${esc(S().chatDrafts[p.id]||'')}</textarea>`}<button type="button" data-action="wx-emoji" aria-label="表情"><span class="wx-smile">☺</span></button><button type="button" data-action="wx-attach" aria-label="添加">${icon('plus')}</button>${!voiceMode&&(S().chatDrafts[p.id]||'').trim()?'<button class="wx-send" type="submit">发送</button>':''}</form>${emojiMenu?`<div class="wx-extra-panel wx-emojis">${['🙂','❤️','😂','🌊','🌅','✨','🥺','😎','👍','👀','🤍','🌙'].map(x=>btn('wx-insert-emoji',x,'',`data-emoji="${x}"`)).join('')}</div>`:''}${mediaMenu?`<div class="wx-extra-panel"><button data-action="wx-pick-photo">${icon('grid')}<span>照片</span></button><button data-action="wx-import">${icon('volume')}<span>导入原声</span></button><button data-action="favorites">${icon('star')}<span>收藏</span></button></div>`:''}</section>`;
 }
 function chatMenu(){modal('phone-actions',{title:'微信',items:[{action:'wx-new',label:'新建聊天',glyph:'bubble'},{action:'wx-self-album',label:'照片',glyph:'grid'},{action:'favorites',label:'收藏',glyph:'star'}]});}
 async function toggleVoice(id,roomId){if(playing===id){stopAudio();return;}stopAudio();const m=messages(roomId).find(x=>x.id===id);if(!m)return;let url=m.src;if(!url){const blob=await mediaLoad(m.blobKey);if(!blob){toast('原声文件不可用，请重新导入');return;}url=URL.createObjectURL(blob);activeUrl=url;}const next=new Audio(url);audio=next;playing=id;next.onended=()=>{if(audio===next){playing=null;audio=null;document.querySelector(`[data-action="wx-voice"][data-id="${id}"]`)?.classList.remove('playing');}if(!m.src)URL.revokeObjectURL(url);};next.onerror=()=>{stopAudio();toast('这段音频暂时无法播放');if(!m.src)URL.revokeObjectURL(url);};try{await next.play();if(audio!==next)return;if(!S().playedVoiceIds.includes(id)){S().playedVoiceIds.push(id);save();}const b=document.querySelector(`[data-action="wx-voice"][data-id="${id}"]`);b?.classList.add('playing');b?.parentElement.querySelector('.wx-voice-unheard')?.remove();}catch{stopAudio();toast('点一下语音条重新播放');}}
 upload.addEventListener('change',async()=>{const file=upload.files?.[0],roomId=ctx.getRoute().id;upload.value='';if(!file||!roomId)return;if(file.size>30*1024*1024){toast('请选择小于30MB的音频');return;}const url=URL.createObjectURL(file),probe=new Audio();probe.preload='metadata';probe.src=url;probe.onloadedmetadata=async()=>{const duration=probe.duration;URL.revokeObjectURL(url);if(!Number.isFinite(duration)||duration<=0){toast('无法读取音频时长');return;}const id='voice_'+Date.now();try{await mediaStore(id,file);S().chatMessages[roomId]||=[];S().chatMessages[roomId].push({id,type:'voice',blobKey:id,duration,from:'clip',name:file.name,time:new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())});save();mediaMenu=false;voiceMode=false;ctx.render();requestAnimationFrame(()=>document.querySelector('#wx-chat-bottom')?.scrollIntoView({block:'end'}));}catch{toast('无法保存音频，请检查浏览器存储权限');}};probe.onerror=()=>{URL.revokeObjectURL(url);toast('无法读取这个音频格式');};});
 function moments(){return nav('朋友圈',`<div class="wx-moments-cover"><img src="${esc(photoList('xiaowang').find(p=>p.id==='xiaowang-05')?.path||'')}" alt="雪山"><h2>小圣</h2>${avatar({id:'self'},true)}</div><div class="wx-moments-feed">${G.albums.map(a=>`<article><h3>${esc(a.name)}</h3><div class="wx-moments-grid">${photoList(a.id).map((f,i)=>`<button data-action="wx-feed-photo" data-album="${a.id}" data-index="${i}"><img src="${esc(f.path)}" alt="${esc(f.description)}"></button>`).join('')}</div></article>`).join('')}</div>`);}
 function profileSheet(){const p=person(ctx.getRoute().id);modal('phone-actions',{title:p.name,avatar:p.id,items:[{action:'wx-album',label:'照片与视频',glyph:'grid'},{action:'wx-import',label:'导入原声',glyph:'volume'},...(p.id===wang?[{action:'wx-replies-toggle',label:'自动回复 · '+(R.enabled()?'已开启':'已暂停')+'（'+R.mode()+'）',glyph:'bubble'}]:[]),{action:'favorites',label:'收藏',glyph:'star'}]});}
 function safari(){return shell('Safari',`<div class="browser-bar safari-address" data-action="search" role="button" tabindex="0">${icon('search')}搜索</div><div class="padded safari-start"><h2>个人收藏</h2><div class="safari-bookmarks">${[['photos','照片','grid'],['wechat','微信','bubble'],['notes','备忘录','edit'],['favorites','收藏','star']].map(([app,name,i])=>btn('app',`<span>${icon(i)}</span><b>${name}</b>`,'',`data-app="${app}"`)).join('')}</div><h2>最近浏览</h2><div class="safari-history">${S().opened.filter(x=>!['home','safari','douyin'].includes(x)).slice(-6).reverse().map(app=>btn('app',`${icon('clock')}<span>${({wechat:'微信',room:'聊天',photos:'照片',notes:'备忘录',settings:'设置',album:'相册',calculator:'计算器',files:'文件',favorites:'收藏'})[app]||'手机'}</span>${icon('chevron')}`,'list-row',`data-app="${app==='room'?'wechat':app==='album'?'photos':app}"`)).join('')}</div></div>`);}
 function calculator(){return shell('计算器',`<div class="calc-screen"><div class="calc-display" aria-live="polite">${esc(calcValue)}</div><div class="calc-grid">${['AC','±','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','0','.','='].map(k=>btn('calc-key',k,'calc-key '+('÷×−+='.includes(k)?'operator':['AC','±','%'].includes(k)?'function-key':k==='0'?'zero':''),`data-key="${k}"`)).join('')}</div></div>`,{className:'calculator-app'});}
 function calc(k){if(/^\d$/.test(k)){calcValue=calcFresh||calcValue==='0'?k:(calcValue.length<12?calcValue+k:calcValue);calcFresh=false;}else if(k==='.'){if(calcFresh){calcValue='0';calcFresh=false;}if(!calcValue.includes('.'))calcValue+='.';}else if(k==='AC'){calcValue='0';calcStored=null;calcOp=null;calcFresh=false;}else if(k==='±')calcValue=String(-Number(calcValue));else if(k==='%')calcValue=String(Number(calcValue)/100);else{if(k==='='&&['520','0520'].includes(calcValue)&&calcStored===null){egg('calculator-0520','0520，记住了。');go('album',{id:'xiaowang'});return;}const value=Number(calcValue);if(calcStored!==null&&calcOp&&!calcFresh){const n=calcOp==='+'?calcStored+value:calcOp==='−'?calcStored-value:calcOp==='×'?calcStored*value:value===0?NaN:calcStored/value;calcValue=Number.isFinite(n)?String(Number(n.toPrecision(10))):'错误';}calcStored=k==='='?null:Number(calcValue);calcOp=k==='='?null:k;calcFresh=true;}const display=document.querySelector('.calc-display');if(display)display.textContent=calcValue;}
 function egg(id,text){if(!S().discovered.includes(id)){S().discovered.push(id);save();}toast(text);}
 function beforeRender(){const scroll=document.querySelector('.wx-chat-scroll');if(!scroll)return;const input=document.getElementById('wx-message-input'),id=scroll.dataset.roomId,old=chatViews.get(id);chatViews.set(id,{top:scroll.scrollTop,atEnd:scroll.scrollHeight-scroll.clientHeight-scroll.scrollTop<80,start:input?.selectionStart??old?.start,end:input?.selectionEnd??old?.end});}
 function afterRender(){const input=sizeComposer(),scroll=document.querySelector('.wx-chat-scroll');if(!scroll)return;const id=scroll.dataset.roomId,view=chatViews.get(id),caret=nextCaret?.id===id?nextCaret:view;scroll.scrollTop=forceChatEnd===id||!view||view.atEnd?scroll.scrollHeight:view.top;if(input&&typeof caret?.start==='number')input.setSelectionRange(Math.min(input.value.length,caret.start),Math.min(input.value.length,caret.end??caret.start));if(nextCaret?.id===id)nextCaret=null;if(forceChatEnd===id)forceChatEnd=null;}
 function sizeComposer(el=document.getElementById('wx-message-input')){if(el){el.style.height='auto';el.style.height=Math.min(85,el.scrollHeight)+'px';}return el;}
 function send(){const id=ctx.getRoute().id,text=(S().chatDrafts[id]||'').trim();if(!text)return;S().chatMessages[id]||=[];const message={id:'text_'+Date.now()+'_'+Math.random().toString(36).slice(2,6),type:'text',text,from:'self',time:new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())};S().chatMessages[id].push(message);S().chatDrafts[id]='';emojiMenu=false;if(id===wang)R.enqueue(message);forceChatEnd=id;save();ctx.render();sizeComposer()?.focus({preventScroll:true});}

 function action(a,t){switch(a){case'wx-replies-toggle':{const on=R.toggle();ctx.closeModal();ctx.render();toast(on?'小王自动回复已开启':'小王自动回复已暂停');return true;}case'wx-tab':tab=t.dataset.tab;mediaMenu=false;emojiMenu=false;ctx.render();return true;case'wx-new':tab='contacts';ctx.closeModal();go('wechat');return true;case'wx-options':chatMenu();return true;case'wx-room-info':profileSheet();return true;case'wx-attach':mediaMenu=!mediaMenu;emojiMenu=false;ctx.render();return true;case'wx-mic':voiceMode=!voiceMode;mediaMenu=false;emojiMenu=false;ctx.render();return true;case'wx-emoji':emojiMenu=!emojiMenu;mediaMenu=false;ctx.render();return true;case'wx-insert-emoji':{const id=ctx.getRoute().id,text=S().chatDrafts[id]||'',input=document.getElementById('wx-message-input'),start=input?.selectionStart??text.length,end=input?.selectionEnd??start,emoji=t.dataset.emoji||'',draft=text.slice(0,start)+emoji+text.slice(end);if(draft.length>1000){toast('最多输入1000个字符');return true;}S().chatDrafts[id]=draft;nextCaret={id,start:start+emoji.length,end:start+emoji.length};voiceMode=false;save();ctx.render();return true;}case'wx-import':ctx.closeModal();upload.click();return true;case'wx-photo':modal('photo',{albumId:'xiaowang',index:Number(t.dataset.index)});return true;case'wx-feed-photo':modal('photo',{albumId:t.dataset.album,index:Number(t.dataset.index)});return true;case'wx-album':{const r=ctx.getRoute();ctx.closeModal();go('album',{id:'xiaowang',...(r.app==='room'?{returnRoom:r.id}:{})});return true;}case'wx-self-album':go('album',{id:'fitness'});return true;case'wx-moments':go('moments');return true;case'wx-pick-photo':modal('phone-actions',{title:'照片',photos:photoList('xiaowang').map((p,i)=>({path:p.path,index:i}))});return true;case'wx-send-photo':{const id=ctx.getRoute().id;S().chatMessages[id]||=[];S().chatMessages[id].push({id:'photo_'+Date.now(),type:'photo',assetId:photoList('xiaowang')[Number(t.dataset.index)]?.id,from:'self'});forceChatEnd=id;save();ctx.closeModal();mediaMenu=false;ctx.render();return true;}case'wx-voice':toggleVoice(t.dataset.id,t.dataset.room);return true;case'calc-key':calc(t.dataset.key);return true;case'wx-egg':egg('settings-profile','有些照片，值得再看一遍。');go('album',{id:'xiaowang'});return true;default:return false;}}
 function input(el){if(el.id==='wx-contact-search'){document.getElementById('wx-contact-list').innerHTML=rows(people.filter(p=>(p.name+' '+(p.alias||'')).toLowerCase().includes(el.value.trim().toLowerCase())));return true;}if(el.id==='wx-message-input'){const id=ctx.getRoute().id;S().chatDrafts[id]=el.value;save();const form=el.closest('form');let send=form.querySelector('.wx-send');if(el.value.trim()&&!send){send=document.createElement('button');send.type='submit';send.className='wx-send';send.textContent='发送';form.appendChild(send);}else if(!el.value.trim()&&send)send.remove();sizeComposer(el);return true;}return false;}
 function renderActions(data){return `<h2>${esc(data.title)}</h2>${data.photos?`<div class="wx-pick-grid">${data.photos.map(p=>btn('wx-send-photo',`<img src="${esc(p.path)}" alt="照片">`,'',`data-index="${p.index}"`)).join('')}</div>`:`<div class="list-group">${(data.items||[]).map(x=>btn(x.action,icon(x.glyph)+`<span class="row-label">${esc(x.label)}</span>`+icon('chevron'),'list-row')).join('')}</div>`}`;}
 return {wechat,room,moments,safari,calculator,action,input,send,stopAudio,unreadCount,markRead,renderActions,avatar,egg,onNavigate(){stopAudio();mediaMenu=false;emojiMenu=false;voiceMode=false;},beforeRender,afterRender};
}};
